import { supabase } from './supabase.js';
import { openMemberProfile } from './member-profile-card.js';

const session=(await supabase.auth.getSession()).data.session;
if(session)initialize(session.user);

async function initialize(user){
  const {data:own}=await supabase.from('profiles').select('role').eq('id',user.id).maybeSingle(),isAdmin=own?.role==='admin';
  const icon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 13v-1a8 8 0 0 1 16 0v1"/><path d="M6 12H5a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h2v-7Zm12 0h1a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2h-2v-7Z"/><path d="M17 19c-1 2-3 2-5 2"/></svg>',send='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 14-7-4 14-3-5-7-2Zm7 2 7-9"/></svg>';
  const widget=document.createElement('section');widget.className=`support-widget${isAdmin?' support-widget-admin':''}`;
  widget.innerHTML=`<button class="support-trigger" type="button" aria-label="Ouvrir le support" aria-expanded="false">${icon}<b hidden></b></button><div class="support-panel" hidden><header><div><span class="eyebrow">${isAdmin?'ESPACE STAFF':'AIDE & SUPPORT'}</span><strong>${isAdmin?'Boîte support':'Support STOA'}</strong><small>${isAdmin?'Demandes des membres':'Académie, compte et abonnement'}</small></div><button type="button" data-support-close aria-label="Fermer">×</button></header><button class="support-back" type="button" hidden>← Toutes les conversations</button><div class="support-roster-search" ${isAdmin?'':'hidden'}><input type="search" placeholder="Rechercher une demande…" aria-label="Rechercher une demande"></div><div class="support-content"><p class="support-loading">Ouverture du support…</p></div><form class="support-form" hidden><label class="support-anonymous-choice"><input type="checkbox" data-support-anonymous><span>Poser cette question anonymement</span></label><div class="support-compose-row"><textarea rows="1" maxlength="2000" placeholder="${isAdmin?'Répondre en tant que Support STOA…':'Posez votre question au support…'}" aria-label="Votre message" required></textarea><button type="submit" aria-label="Envoyer">${send}</button></div></form><p class="support-status" role="status"></p></div>`;document.body.append(widget);
  const trigger=widget.querySelector('.support-trigger'),panel=widget.querySelector('.support-panel'),content=widget.querySelector('.support-content'),form=widget.querySelector('.support-form'),back=widget.querySelector('.support-back'),status=widget.querySelector('.support-status'),search=widget.querySelector('[type="search"]'),roster=widget.querySelector('.support-roster-search'),anonymousChoice=widget.querySelector('.support-anonymous-choice'),anonymousInput=widget.querySelector('[data-support-anonymous]');
  let conversations=[],messages=[],active=null,draftAnonymous=false,channel,refreshTimer;
  const esc=(value='')=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'),norm=(value='')=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),time=value=>new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
  const supportAvatar='<span class="support-avatar support-avatar-staff"><img src="/assets/branding/stoa-mark-400.png" alt=""></span>',anonymousAvatar='<span class="support-avatar support-avatar-anonymous">?</span>';
  const selected=()=>conversations.find(item=>item.conversation_id===active);
  const avatar=(item,clickable=false)=>{if(item?.is_anonymous)return anonymousAvatar;const tag=clickable&&item?.member_id?'button':'span',attrs=tag==='button'?`type="button" data-member-profile="${item.member_id}"`:'aria-hidden="true"';return item?.avatar_url?`<${tag} class="support-avatar has-image" ${attrs}><img src="${esc(item.avatar_url)}" alt=""></${tag}>`:`<${tag} class="support-avatar" ${attrs}>${esc((item?.display_name||'S')[0])}</${tag}>`;};
  function unread(){const count=conversations.reduce((sum,item)=>sum+Number(item.unread_count||0),0),badge=trigger.querySelector('b');badge.textContent=count?(count>9?'9+':count):'';badge.hidden=!count;trigger.classList.toggle('has-unread',Boolean(count));}
  async function loadConversations(){const {data,error}=await supabase.rpc(isAdmin?'get_support_inbox':'get_my_support_conversations');if(error){content.innerHTML=`<p class="support-empty">Le support est indisponible.<br>${esc(error.message)}</p>`;return false;}conversations=data||[];unread();return true;}
  async function loadThread(){if(!active){messages=[];return;}const {data,error}=await supabase.rpc('get_support_thread',{p_conversation_id:active});messages=error?[]:(data||[]);status.textContent=error?.message||'';}
  async function markRead(){if(panel.hidden||!active)return;await supabase.rpc('mark_support_thread_read',{p_conversation_id:active});const item=selected();if(item)item.unread_count=0;unread();}
  function renderThread(){const conversation=selected(),isAnonymous=conversation?.is_anonymous??draftAnonymous;const head=isAdmin?`<div class="support-thread-member">${avatar(conversation,true)}<div><small>DEMANDE ${isAnonymous?'ANONYME':'DE'}</small><strong>${esc(isAnonymous?'Membre anonyme':conversation?.display_name||'Membre STOA')}</strong>${!isAnonymous&&conversation?.username?`<span>@${esc(conversation.username)}</span>`:''}</div></div>`:`<div class="support-welcome"><span>?</span><div><strong>${isAnonymous?'Question anonyme':'Une question ?'}</strong><p>${isAnonymous?'Votre identité reste invisible pour le staff. La réponse reste liée à votre compte.':'Un membre du staff STOA vous répondra ici.'}</p></div></div>`;
    const rows=messages.map(item=>{const mine=item.sender_kind===(isAdmin?'support':'member'),fromSupport=item.sender_kind==='support';return `<article class="support-message ${mine?'mine':fromSupport?'support-reply':'support-member-message'}"><header>${fromSupport?supportAvatar:isAnonymous?anonymousAvatar:''}<strong>${fromSupport?(isAdmin&&mine?'Vous · Support':'Support STOA'):(isAdmin?(isAnonymous?'Membre anonyme':esc(conversation?.display_name||'Membre STOA')):'Vous')}</strong><time>${time(item.created_at)}</time></header><p>${esc(item.content).replaceAll('\n','<br>')}</p></article>`;}).join('');
    content.innerHTML=`${head}${rows||'<p class="support-empty">Aucun message pour le moment.<br>Posez votre première question ici.</p>'}`;content.scrollTop=content.scrollHeight;form.hidden=false;back.hidden=isAdmin?false:conversations.length===0&&!active;roster.hidden=true;anonymousChoice.hidden=isAdmin||Boolean(active);anonymousInput.checked=isAnonymous;markRead();}
  function renderList(){const query=norm(search?.value||''),filtered=conversations.filter(item=>!query||norm(`${item.display_name||''} ${item.username||''} ${item.last_message||''}`).includes(query));const rows=filtered.map(item=>`<div class="support-conversation"><button class="support-conversation-open" type="button" data-support-conversation="${item.conversation_id}">${avatar(item)}<span><strong>${esc(item.is_anonymous?'Conversation anonyme':item.display_name||(isAdmin?'Membre STOA':'Conversation identifiée'))}</strong><small>${esc(item.last_message||'Nouvelle demande')}</small></span><span><time>${item.last_message_at?time(item.last_message_at):''}</time>${Number(item.unread_count)?`<b>${Number(item.unread_count)>9?'9+':Number(item.unread_count)}</b>`:''}</span></button></div>`).join('');const choices=!isAdmin?'<div class="support-new-choices"><p>Comment souhaitez-vous poser votre question ?</p><button type="button" data-support-new="identified"><strong>Avec mon identité</strong><small>Le staff voit votre nom.</small></button><button type="button" data-support-new="anonymous"><strong>Anonymement</strong><small>Votre identité reste masquée au staff.</small></button></div>':'';content.innerHTML=choices+(rows||(isAdmin?'<p class="support-empty">Aucune demande pour le moment.</p>':''));form.hidden=true;back.hidden=true;roster.hidden=!isAdmin;}
  const render=()=>active||(!isAdmin&&!conversations.length)?renderThread():renderList();
  async function refresh({autoOpen=true}={}){if(!await loadConversations())return;if(active&&!conversations.some(item=>item.conversation_id===active))active=null;if(active)await loadThread();else if(!isAdmin&&conversations.length===1&&autoOpen){active=conversations[0].conversation_id;draftAnonymous=conversations[0].is_anonymous;await loadThread();}render();}
  const fit=()=>{if(panel.hidden||!matchMedia('(max-width:760px)').matches){panel.classList.remove('support-viewport-fit');panel.style.removeProperty('top');panel.style.removeProperty('height');return;}const viewport=window.visualViewport,height=viewport?.height||innerHeight;panel.classList.add('support-viewport-fit');panel.style.top=`${(viewport?.offsetTop||0)+64}px`;panel.style.height=`${Math.max(160,height-72)}px`;requestAnimationFrame(()=>content.scrollTop=content.scrollHeight);};
  const toggle=open=>{panel.hidden=!open;trigger.setAttribute('aria-expanded',String(open));widget.classList.toggle('support-open',open);if(open){refresh();refreshTimer||=setInterval(()=>{if(!panel.hidden)refresh({autoOpen:false});},isAdmin?15000:30000);requestAnimationFrame(fit);}else fit();};
  trigger.addEventListener('click',()=>{const opening=panel.hidden;toggle(opening);if(opening)dispatchEvent(new CustomEvent('stoa:support-opened'));});widget.querySelector('[data-support-close]').addEventListener('click',()=>toggle(false));
  content.addEventListener('click',async event=>{const profile=event.target.closest('[data-member-profile]');if(profile&&isAdmin)return openMemberProfile(profile.dataset.memberProfile);const thread=event.target.closest('[data-support-conversation]');if(thread){active=thread.dataset.supportConversation;draftAnonymous=Boolean(selected()?.is_anonymous);await loadThread();return renderThread();}const fresh=event.target.closest('[data-support-new]');if(fresh){draftAnonymous=fresh.dataset.supportNew==='anonymous';const existing=conversations.find(item=>Boolean(item.is_anonymous)===draftAnonymous);active=existing?.conversation_id||null;if(active)await loadThread();else messages=[];renderThread();}});
  back.addEventListener('click',()=>{active=null;messages=[];renderList();});search?.addEventListener('input',renderList);anonymousInput.addEventListener('change',()=>{draftAnonymous=anonymousInput.checked;renderThread();});
  form.addEventListener('submit',async event=>{event.preventDefault();const textarea=form.querySelector('textarea'),value=textarea.value.trim();if(!value)return;const button=form.querySelector('[type="submit"]');button.disabled=true;status.textContent='';const {data,error}=await supabase.rpc('send_support_message',{p_conversation_id:active,p_content:value,p_anonymous:draftAnonymous});button.disabled=false;if(error){status.textContent=error.message;return;}active=data;textarea.value='';textarea.style.height='';await refresh({autoOpen:false});});
  form.querySelector('textarea').addEventListener('input',event=>{event.currentTarget.style.height='';event.currentTarget.style.height=`${Math.min(96,event.currentTarget.scrollHeight)}px`;});form.querySelector('textarea').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();form.requestSubmit();}});form.querySelector('textarea').addEventListener('focus',()=>setTimeout(fit,120));window.visualViewport?.addEventListener('resize',fit);window.visualViewport?.addEventListener('scroll',fit);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden)toggle(false);});
  await refresh();channel=supabase.channel(`support:${user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'support_messages'},()=>refresh({autoOpen:false})).subscribe();addEventListener('pagehide',()=>{if(channel)supabase.removeChannel(channel);clearInterval(refreshTimer);window.visualViewport?.removeEventListener('resize',fit);window.visualViewport?.removeEventListener('scroll',fit);},{once:true});
}
